from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class SmokeAsset:
    name: str
    format: str
    path: Path


def discover_assets(root: Path) -> list[SmokeAsset]:
    assets: list[SmokeAsset] = []
    for path in sorted(root.rglob("*")):
        if not path.is_file():
            continue
        name = path.relative_to(root).as_posix()
        if path.suffix.lower() == ".pdf":
            assets.append(SmokeAsset(name, "pdf", path))
        elif path.suffix.lower() == ".epub":
            assets.append(SmokeAsset(name, "epub", path))
    return assets

from typing import Any

from pdf_craft import (
    DeepSeekOCR2LocalConfig,
    DeepSeekOCR2VendorConfig,
    DeepSeekOCRLocalConfig,
    DeepSeekOCRVendorConfig,
    OCRConfig,
    OCRMode,
    UnlimitedOCRLocalConfig,
    UnlimitedOCRVendorConfig,
)


def create_ocr_config(mode: OCRMode, values: dict[str, Any]) -> OCRConfig:
    """Build an OCR config from explicit caller-supplied values only."""
    if mode == "deepseek-ocr-local":
        return DeepSeekOCRLocalConfig(**values)
    if mode == "deepseek-ocr2-local":
        return DeepSeekOCR2LocalConfig(**values)
    if mode == "unlimited-ocr-local":
        return UnlimitedOCRLocalConfig(**values)
    if mode == "deepseek-ocr-vendor":
        return DeepSeekOCRVendorConfig(**values)
    if mode == "deepseek-ocr2-vendor":
        return DeepSeekOCR2VendorConfig(**values)
    if mode == "unlimited-ocr-vendor":
        return UnlimitedOCRVendorConfig(**values)
    raise ValueError(f"unsupported OCR mode: {mode}")

import json
import re
import zipfile
from posixpath import normpath
from pathlib import Path
from xml.etree import ElementTree
from urllib.parse import urlparse

import pypdf

from pdf_craft.document import DocumentPackage
from pdf_craft.extractor.chapter.chapter import ParagraphLayout
from pdf_craft.extractor.chapter.reader import create_chapters_reader


def check_package(package: DocumentPackage, require_geometry: bool = False) -> list[str]:
    package.validate()
    errors: list[str] = []
    chapters = sorted(package.chapters_path.glob("chapter*.xml"))
    if not chapters:
        errors.append("DocumentPackage contains no chapter XML")
    for chapter in chapters:
        try:
            ElementTree.parse(chapter)
        except ElementTree.ParseError as error:
            errors.append(f"invalid chapter XML {chapter.name}: {error}")
    if package.has_toc():
        try:
            ElementTree.parse(package.toc_path)  # type: ignore[arg-type]
        except ElementTree.ParseError as error:
            errors.append(f"invalid toc.xml: {error}")
    if require_geometry and not package.page_pixel_sizes():
        errors.append("DocumentPackage lacks required page geometry metadata")
    return errors


def check_pdf_patch_geometry(package: DocumentPackage) -> list[str]:
    """Require package-owned geometry for every block a PDF patch may replace.

    The PDF pipeline can otherwise re-render a source page when geometry is
    absent. Smoke runs must reject that fallback so their package contract is
    explicit and reproducible.
    """
    if package.metadata_path is None or not package.metadata_path.exists():
        return ["PDF patch requires DocumentPackage document.json geometry metadata"]
    try:
        page_sizes = package.page_pixel_sizes()
    except (OSError, ValueError, json.JSONDecodeError) as error:
        return [f"PDF patch has invalid DocumentPackage geometry metadata: {error}"]
    needed_pages: set[int] = set()
    for chapter in create_chapters_reader(package.chapters_path)():
        for layout in chapter.layouts:
            if isinstance(layout, ParagraphLayout) and layout.ref in {"text", "sub_title"}:
                needed_pages.update(block.page_index for block in layout.blocks if block.content)
    missing = sorted(needed_pages - set(page_sizes))
    if missing:
        return [f"PDF patch geometry missing for replacement pages: {missing}"]
    return []


def check_markdown(path: Path, _assets_path: Path | None = None) -> list[str]:
    """Validate local image links relative to the Markdown document.

    ``assets_path`` is retained as an ignored compatibility parameter.  The
    target path in Markdown is always interpreted from ``path.parent``.
    """
    if not path.is_file() or not path.read_text(encoding="utf-8").strip():
        return ["Markdown output is missing or empty"]
    errors: list[str] = []
    for target in re.findall(r"!\[[^]]*\]\(([^)]+)\)", path.read_text(encoding="utf-8")):
        target = target.strip().split(maxsplit=1)[0].strip("<>")
        parsed = urlparse(target)
        if not target or target.startswith("#") or parsed.scheme or parsed.netloc:
            continue
        target_path = Path(target)
        if not target_path.is_absolute():
            target_path = path.parent / target_path
        if not target_path.exists():
            errors.append(f"Markdown image reference is missing: {target}")
    return errors


def check_epub(path: Path) -> list[str]:
    if not zipfile.is_zipfile(path):
        return ["EPUB output is not a ZIP file"]
    with zipfile.ZipFile(path) as archive:
        names = {name for name in archive.namelist() if not name.endswith("/")}
        errors: list[str] = []
        if "mimetype" not in names:
            return ["EPUB missing mimetype"]
        if "META-INF/container.xml" not in names:
            return ["EPUB missing META-INF/container.xml"]
        container = _parse_archive_xml(archive, "META-INF/container.xml", errors)
        if container is None:
            return errors
        rootfiles = [element for element in container.iter() if _local_name(element.tag) == "rootfile"]
        opf_paths = [element.get("full-path") for element in rootfiles if element.get("full-path")]
        if len(opf_paths) != 1:
            return errors + ["container.xml must declare exactly one OPF rootfile"]
        opf_path = opf_paths[0]
        if opf_path not in names:
            return errors + [f"container.xml references missing OPF: {opf_path}"]
        opf = _parse_archive_xml(archive, opf_path, errors)
        if opf is None:
            return errors
        return errors + _check_opf(archive, names, opf_path, opf)


def _check_opf(archive, names: set[str], opf_path: str, opf) -> list[str]:
    errors: list[str] = []
    manifest = _first_child(opf, "manifest")
    spine = _first_child(opf, "spine")
    if manifest is None:
        errors.append("OPF missing manifest")
    if spine is None:
        errors.append("OPF missing spine")
    if manifest is None or spine is None:
        return errors
    opf_dir = str(Path(opf_path).parent).replace(".", "", 1).strip("/")
    items: dict[str, tuple[str, str, set[str]]] = {}
    for item in _children(manifest, "item"):
        item_id, href = item.get("id"), item.get("href")
        if not item_id or not href:
            errors.append("OPF manifest item missing id or href")
            continue
        item_path = _resolve(opf_dir, href)
        if item_id in items:
            errors.append(f"OPF manifest has duplicate id: {item_id}")
        items[item_id] = (item_path, item.get("media-type", ""), set(item.get("properties", "").split()))
        if item_path not in names:
            errors.append(f"OPF manifest references missing resource: {item_path}")
    spine_items = _children(spine, "itemref")
    if not spine_items:
        errors.append("OPF spine has no itemref")
    spine_paths: list[str] = []
    for itemref in spine_items:
        idref = itemref.get("idref")
        if not idref or idref not in items:
            errors.append(f"OPF spine references missing manifest id: {idref}")
            continue
        spine_paths.append(items[idref][0])
    for chapter_path in spine_paths:
        _parse_archive_xml(archive, chapter_path, errors, "spine XHTML")
    errors.extend(_check_toc(archive, names, opf, items, spine))
    return errors


def _check_toc(archive, names: set[str], opf, items, spine) -> list[str]:
    version = opf.get("version", "2.0")
    if version.startswith("3"):
        nav_items = [item for item in items.values() if "nav" in item[2]]
        if len(nav_items) != 1:
            return ["EPUB 3 OPF must declare exactly one navigation manifest item"]
        nav_path = nav_items[0][0]
        nav = _parse_archive_xml(archive, nav_path, [], "navigation document")
        if nav is None:
            return [f"invalid navigation document: {nav_path}"]
        toc_navs = [element for element in nav.iter() if _local_name(element.tag) == "nav" and "toc" in _property_tokens(element)]
        if not toc_navs:
            return ["EPUB 3 navigation document has no toc nav"]
        return _check_toc_links(toc_navs[0], names, str(Path(nav_path).parent).strip("."))
    ncx_id = spine.get("toc")
    if not ncx_id or ncx_id not in items:
        return ["EPUB 2 spine must reference an NCX manifest item"]
    ncx_path = items[ncx_id][0]
    ncx = _parse_archive_xml(archive, ncx_path, [], "NCX")
    if ncx is None:
        return [f"invalid NCX: {ncx_path}"]
    if not any(_local_name(element.tag) == "navMap" for element in ncx.iter()):
        return ["NCX has no navMap"]
    return _check_toc_links(ncx, names, str(Path(ncx_path).parent).strip("."), attribute="src")


def _check_toc_links(root, names: set[str], base_dir: str, attribute: str = "href") -> list[str]:
    errors: list[str] = []
    links = [element.get(attribute) for element in root.iter() if _local_name(element.tag) in {"a", "content"} and element.get(attribute)]
    if not links:
        return ["TOC contains no links"]
    for link in links:
        target = _resolve(base_dir, link.split("#", 1)[0])
        if target and target not in names:
            errors.append(f"TOC link references missing resource: {target}")
    return errors


def _parse_archive_xml(archive, name: str, errors: list[str], label: str = "XML"):
    try:
        return ElementTree.fromstring(archive.read(name))
    except (KeyError, ElementTree.ParseError) as error:
        errors.append(f"invalid {label} {name}: {error}")
        return None


def _resolve(base_dir: str, href: str) -> str:
    if not href:
        return ""
    return normpath(f"{base_dir}/{href}").lstrip("./")


def _local_name(tag: str) -> str:
    return tag.rsplit("}", 1)[-1]


def _children(element, name: str):
    return [child for child in element if _local_name(child.tag) == name]


def _first_child(element, name: str):
    return next(iter(_children(element, name)), None)


def _property_tokens(element) -> set[str]:
    return set(element.get("{http://www.idpf.org/2007/ops}type", "").split()) | set(element.get("epub:type", "").split())


def check_pdf(path: Path, expected_pages: int) -> list[str]:
    try:
        reader = pypdf.PdfReader(str(path))
    except Exception as error:
        return [f"PDF output cannot be opened: {error}"]
    if len(reader.pages) != expected_pages:
        return [f"PDF page count changed: expected {expected_pages}, got {len(reader.pages)}"]
    return []

    return _smoke_exit_code(run_path)


def _run_matrix(args: argparse.Namespace) -> int:
    config = json.loads(args.config.read_text(encoding="utf-8"))
    runs = expand_matrix(config, args.assets_root)
    env_error: str | None = None
    if any(_matrix_run_needs_env(run) for run in runs):
        try:
            load_project_env(_project_root())
        except SystemExit as error:
            env_error = str(error)
    exit_code = 0
    for run in runs:
        if env_error and _matrix_run_needs_env(run):
            run = replace(run, configuration_error=env_error)
        else:
            try:
                run = _resolve_matrix_runtime(run, args.output_root)
            except SystemExit as error:
                run = replace(run, configuration_error=str(error))
        run_path = run_smoke(run, assets_root=args.assets_root, output_root=args.output_root, dry_run=args.dry_run)
        print(run_path)
        exit_code = max(exit_code, _smoke_exit_code(run_path))
    return exit_code


def _smoke_exit_code(run_path: Path) -> int:
    """Return a non-zero code for failed or skipped required smoke runs."""
    try:
        status = json.loads((run_path / "checks.json").read_text(encoding="utf-8"))["status"]
    except (OSError, KeyError, json.JSONDecodeError):
        return 1
    return 0 if status in {"passed", "planned"} else 1


def _matrix_run_needs_env(run: SmokeRun) -> bool:
    if run.backend and run.ocr is None:
        return True
    translation = run.translation or {}
    return any(
        key in translation
        for key in ("llm_profile", "translation_llm_profile", "fill_llm_profile")
    )


def _resolve_matrix_runtime(run: SmokeRun, output_root: Path) -> SmokeRun:
    _validate_ocr_size(run.backend, run.ocr_size)
    ocr = run.ocr
    if run.backend and ocr is None:
        ocr = ocr_values_from_env(run.backend)
    translation = _resolve_translation_profiles(run.translation, output_root)
    return replace(run, ocr=ocr, translation=translation)


def _resolve_translation_profiles(translation: dict[str, Any] | None, output_root: Path) -> dict[str, Any] | None:
    if not translation:
        return translation
    resolved = dict(translation)
    profile = resolved.pop("llm_profile", None)
    translation_profile = resolved.pop("translation_llm_profile", profile)
    fill_profile = resolved.pop("fill_llm_profile", profile)
    if translation_profile and "llm" not in resolved:
        resolved["llm"] = llm_values_from_env(
            str(translation_profile),
            cache_path=output_root / "_c" / "t",
            log_dir_path=output_root / "_l" / "t",
        )
    if fill_profile and fill_profile != translation_profile and "fill_llm" not in resolved:
        resolved["fill_llm"] = llm_values_from_env(
            str(fill_profile),
            cache_path=output_root / "_c" / "f",
            log_dir_path=output_root / "_l" / "f",
        )
    return resolved


def _extract(args: argparse.Namespace, package_path: Path) -> _ExtractionResult:
    load_project_env(_project_root())
    ocr_mode = cast(OCRMode | None, args.ocr_mode) or ocr_mode_from_env()

